// ====================================
// FORMATEAR RESPUESTA DE STOCK
// ====================================

const items = $input.all();
const divisaConsultada = $('Execute Workflow Trigger').first()?.json?.divisa || null;

if (!items || items.length === 0) {
  return {
    json: {
      success: false,
      message: divisaConsultada 
        ? `❌ No se encontró información de stock para: ${divisaConsultada}`
        : '❌ No hay divisas en stock',
      divisas: []
    }
  };
}

// Formatear datos
const divisas = items.map(item => {
  const data = item.json;
  return {
    divisa: data.divisa,
    precio_compra: parseFloat(data.precio_compra || 0),
    precio_venta: parseFloat(data.precio_venta || 0),
    stock_disponible: parseFloat(data.stock_disponible || 0),
    ultima_actualizacion: data.updated_at
  };
});

// Crear respuesta formateada para el chat
let respuestaTexto = '';

if (divisaConsultada && divisas.length === 1) {
  // Consulta específica
  const divisa = divisas[0];
  respuestaTexto = `💰 **STOCK DE ${divisa.divisa.toUpperCase()}**\n━━━━━━━━━━━━━━━━━━\n`;
  respuestaTexto += `📊 **Stock Disponible:** ${divisa.stock_disponible.toLocaleString('es-AR')} unidades\n`;
  respuestaTexto += `💵 **Precio Compra:** $${divisa.precio_compra.toLocaleString('es-AR', {minimumFractionDigits: 2})}\n`;
  respuestaTexto += `💸 **Precio Venta:** $${divisa.precio_venta.toLocaleString('es-AR', {minimumFractionDigits: 2})}\n`;

  const spread = divisa.precio_venta - divisa.precio_compra;
  const spreadPct = divisa.precio_compra > 0 ? ((spread / divisa.precio_compra) * 100).toFixed(2) : 0;
  respuestaTexto += `📈 **Spread:** $${spread.toFixed(2)} (${spreadPct}%)\n`;

  // Alertas de stock
  if (divisa.stock_disponible < 100) {
    respuestaTexto += `\n⚠️ **ALERTA:** Stock bajo (menos de 100 unidades)`;
  } else if (divisa.stock_disponible > 10000) {
    respuestaTexto += `\n✅ Stock abundante`;
  }

} else {
  // Lista completa
  respuestaTexto = `💰 **STOCK DE DIVISAS DISPONIBLES**\n━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

  divisas.forEach(divisa => {
    const stockIcon = divisa.stock_disponible < 100 ? '🔴' : 
                     divisa.stock_disponible < 1000 ? '🟡' : '🟢';

    respuestaTexto += `${stockIcon} **${divisa.divisa.toUpperCase()}**\n`;
    respuestaTexto += `   Stock: ${divisa.stock_disponible.toLocaleString('es-AR')} | `;
    respuestaTexto += `Compra: $${divisa.precio_compra.toLocaleString('es-AR')} | `;
    respuestaTexto += `Venta: $${divisa.precio_venta.toLocaleString('es-AR')}\n\n`;
  });

  respuestaTexto += `\n🔴 Stock crítico | 🟡 Stock medio | 🟢 Stock bueno`;
}

return {
  json: {
    success: true,
    message: respuestaTexto,
    divisas: divisas,
    total_divisas: divisas.length,
    consulta_especifica: !!divisaConsultada
  }
};
